// ---------------------------------------------------------------- export
// Every download goes through save(). `req` describes what is being exported so the paywall
// (BSAccount.gate) can decide: free-tier export, one of the free full-feature exports, or upgrade.
async function save(filename, data, req) {
  if (req && window.BSAccount) { const ok = await window.BSAccount.gate(req); if (!ok) return false; }
  const blob = data instanceof Blob ? data : new Blob([data]);
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = filename;
  document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  toast('Saved ' + filename);
  { const fa = $('fbAfter'); if (fa) fa.hidden = false; } // after a download: invite to the community
  return true;
}
