// hover and click in the view
let sepHoverRaf = 0;
canvas.addEventListener('pointermove', e => {
  if (S.tool !== 'separate' || !sepGroup || sepHoverRaf) return;
  sepHoverRaf = requestAnimationFrame(() => {
    sepHoverRaf = 0;
    const r = canvas.getBoundingClientRect();
    ray.setFromCamera({ x: (e.clientX - r.left) / r.width * 2 - 1, y: -(e.clientY - r.top) / r.height * 2 + 1 }, camera);
    const hit = ray.intersectObjects(sepGroup.children)[0];
    const i = hit ? hit.object.userData.i : -1;
    canvas.style.cursor = i >= 0 ? 'pointer' : '';
    if (i !== SEP.hover) { SEP.hover = i; sepPaint(); }
  });
});
canvas.addEventListener('pointerup', e => {
  if (S.tool !== 'separate' || !sepGroup || !downAt || Math.hypot(e.clientX - downAt[0], e.clientY - downAt[1]) > 4) return;
  const r = canvas.getBoundingClientRect();
  ray.setFromCamera({ x: (e.clientX - r.left) / r.width * 2 - 1, y: -(e.clientY - r.top) / r.height * 2 + 1 }, camera);
  const hit = ray.intersectObjects(sepGroup.children)[0];
  SEP.sel = hit ? (SEP.sel === hit.object.userData.i ? -1 : hit.object.userData.i) : -1; sepPaint();
  const row = document.querySelector(`#sepTable tbody tr[data-i="${SEP.sel}"]`); if (row) row.scrollIntoView({ block: 'nearest' });
});

