  $('outSummary').textContent = { repair: 'Press Repair model or Simplify to make a fixed copy.', relief: 'Press Make relief to build the plaque.', laser: 'Press Make sheets to slice the model.', fx: 'Press Apply effect to restyle the model.', mc: 'Upload a graphic or try a sample to start.', paint: 'Upload a picture or try a sample to start.' }[S.tool] || idleHint();
