  const cols = 14, rows = 5, gapX = 8, gapY = 8, mX = 18, mY = 16;
  const kw = (W - 2 * mX - (cols - 1) * gapX) / cols, kh = (H - 2 * mY - (rows - 1) * gapY) / rows, r = 6;
  const key = (x, y, w, h, col) => { g.fillStyle = col; g.beginPath(); g.moveTo(x + r, y); g.lineTo(x + w - r, y); g.quadraticCurveTo(x + w, y, x + w, y + r); g.lineTo(x + w, y + h - r); g.quadraticCurveTo(x + w, y + h, x + w - r, y + h); g.lineTo(x + r, y + h); g.quadraticCurveTo(x, y + h, x, y + h - r); g.lineTo(x, y + r); g.quadraticCurveTo(x, y, x + r, y); g.closePath(); g.fill(); };
