  if (kind === 'screen') { const tex = lockScreenTex(); return phys({ color: 0xffffff, map: tex, metalness: 0.05, roughness: 0.16, clearcoat: 1, clearcoatRoughness: 0.06, emissive: 0xffffff, emissiveMap: tex, emissiveIntensity: 0.16, envMapIntensity: 0.7 }); }
  if (kind === 'keys') { const tex = keyDeckTex(); return phys({ color: 0xffffff, map: tex, metalness: 0.08, roughness: 0.55, envMapIntensity: 0.4 }); }
  if (kind === 'frame' || kind === 'aluminum' || kind === 'lensRing' || kind === 'button') return phys({ color: hex, metalness: kind === 'aluminum' ? 0.72 : 1, roughness: kind === 'lensRing' ? 0.22 : kind === 'aluminum' ? 0.42 : 0.3, clearcoat: kind === 'aluminum' ? 0.1 : 0.22, clearcoatRoughness: 0.35, envMapIntensity: kind === 'aluminum' ? 0.4 : 0.7 });
  if (kind === 'plateau') return phys({ color: hex, metalness: 0.4, roughness: 0.5, clearcoat: 0.28, clearcoatRoughness: 0.45, envMapIntensity: 0.65 });
  if (kind === 'lensGlass') return phys({ color: hex, metalness: 0.2, roughness: 0.06, clearcoat: 1, clearcoatRoughness: 0.04, iridescence: 1, iridescenceIOR: 1.5, iridescenceThicknessRange: [160, 340], specularColor: new THREE.Color('#8A9AD0'), envMapIntensity: 0.85 });
  if (kind === 'flash') return phys({ color: hex, metalness: 0.15, roughness: 0.2, clearcoat: 0.7, emissive: hex, emissiveIntensity: 0.08, envMapIntensity: 0.7 });
  if (kind === 'island' || kind === 'bezel' || kind === 'sensor' || kind === 'rubber') return phys({ color: hex, metalness: kind === 'sensor' ? 0.2 : 0.06, roughness: kind === 'rubber' ? 0.85 : kind === 'sensor' ? 0.15 : 0.45, iridescence: kind === 'sensor' ? 0.6 : 0, iridescenceThicknessRange: [200, 380], envMapIntensity: 0.45 });
  if (kind === 'trackpad') return phys({ color: hex, metalness: 0.45, roughness: 0.28, clearcoat: 0.55, clearcoatRoughness: 0.2, envMapIntensity: 0.7 });
