  $('outSummary').textContent = `${(p.length / 9).toLocaleString()} triangles`;
  const e = $('outStats'); e.innerHTML = '';
  for (const [v, k] of stats || []) { const d = document.createElement('div'); d.innerHTML = '<b></b><span></span>'; d.firstChild.textContent = v; d.lastChild.textContent = k; e.appendChild(d); }
