  const bb = T.polysBBox(t.polys);
  const S0 = t.polys.map(P => ({ outer: P.outer.map(q => [q[0] - (bb.x0 + bb.x1) / 2, q[1] - (bb.y0 + bb.y1) / 2]), holes: P.holes.map(h => h.map(q => [q[0] - (bb.x0 + bb.x1) / 2, q[1] - (bb.y0 + bb.y1) / 2])) }));
