  for (const [z0, z1, mat] of parts) {
    const h = z1 - z0, geo = new THREE.CylinderGeometry(rad * (mat.metalness ? 1.004 : 1), rad * (mat.metalness ? 1.004 : 1), h, seg, 1, false).rotateX(Math.PI / 2).translate(0, 0, (z0 + z1) / 2);
    const im = new THREE.InstancedMesh(geo, mat, n); im.frustumCulled = false;
    r.centers.forEach((c, i) => { mtx.makeTranslation(c[0], c[1], 0); im.setMatrixAt(i, mtx); });
    im.instanceMatrix.needsUpdate = true; g.add(im);
  }
