  const stats = [stat(`${f1(B0.W)} \u00d7 ${f1(B0.D)} \u00d7 ${f1(B0.H)} mm`, 'outside'), stat(inside, 'inside')];
  if (lid === 'lip') stats.push(stat(`${f1(B0.lipH)} mm lip, ${o.clearance} mm`, 'lid fit'));
  if (lid === 'magnet') stats.push(stat(`4 \u00d7 \u00d8${f1(B0.pocket.d)} \u00d7 ${f1(B0.pocket.depth)} mm`, 'magnet pockets in box and lid'));
  if (set.length > 1) stats.push(stat(`${set.length}`, 'boxes nest inside each other'));
  if (splitNotes.length) stats.push(stat(`${parts.length}`, 'pieces to print (split to the bed)'));
