  const lines = [`Expressarte box maker: ${set.length > 1 ? set.length + ' nesting boxes' : 'one box'}${lid === 'none' ? '' : ' with ' + (lid === 'lip' ? 'lip lids' : 'magnet lids')}.`, ''];
  set.forEach((s, i) => { const B = s.layout; lines.push(`Box ${i + 1}: outside ${f1(B.W)} x ${f1(B.D)} x ${f1(B.H)} mm, wall ${B.wall} mm, floor ${B.floor} mm${s.lid ? ', lid ' + f1(B.lidT) + ' mm' : ''}.`); });
  lines.push('', 'Print the boxes open side up. No supports are needed.');
  if (lid === 'lip') lines.push(`Print each lid lip side up. The lip sits ${o.clearance} mm inside the walls all round; if it is tight, sand the lip or raise the clearance.`);
  if (lid === 'magnet') lines.push(`Magnets: ${o.magD} x ${o.magH} mm discs, 8 per box (4 in the corner posts, 4 in the lid). Pockets are ${f1(B0.pocket.d)} mm wide and ${f1(B0.pocket.depth)} mm deep.`, 'Print each lid pockets up. Press or glue the magnets in flush, and check the poles attract before the glue sets (lid pockets mirror the box pockets when the lid is flipped on).');
