  g.fillStyle = 'rgba(240,200,140,.55)'; g.fillRect(0, H * 0.74, W, H * 0.06); // a lake catching the light
  for (let k = 0; k < 9; k++) { const x = rnd() * W, y = H * (0.72 + rnd() * 0.12), s = H * (0.05 + rnd() * 0.12); g.fillStyle = '#1b2414'; g.beginPath(); g.ellipse(x, y - s, s * 0.35, s * 0.8, 0, 0, Math.PI * 2); g.fill(); g.fillRect(x - 1.5, y - s * 0.3, 3, s * 0.4); }
  for (let k = 0; k < 2600; k++) { const x = rnd() * W, y = rnd() * H, p = g.getImageData(x | 0, y | 0, 1, 1).data; g.strokeStyle = `rgba(${p[0]},${p[1]},${p[2]},.5)`; g.lineWidth = 1 + rnd() * 3; g.beginPath(); g.moveTo(x, y); g.lineTo(x + (rnd() - 0.5) * 14, y + (rnd() - 0.5) * 5); g.stroke(); }
