$('coupon').addEventListener('click', async () => {
  const conn = connOpts();
  if (conn.type === 'none') { toast('Pick a joint type first; flat faces need no fit test.'); return; }
  busy(true, 'Making fit test'); await tick();
  try {
    const sz = conn.type === 'dovetail' ? [70, 50, 30] : conn.type === 'magnet' ? [40, 40, 20] : conn.type === 'lip' ? [40, 50, 30] : [40, 40, 28];
    const box = T.box(0, 0, 0, sz[0], sz[1], sz[2]);
    const planes = [[C.nudgePlane(box, 0, sz[0] / 2)], [], []];
    const g = C.cutGrid(box, planes); const bvh = C.buildBVH(box);
    const o = Object.assign({}, conn, { perFace: conn.type === 'dovetail' ? 1 : 2 });
    const log = C.addConnectors(g.pieces, g.caps, o, bvh);
    if (conn.type === 'lip') C.lipJoints(g.pieces, g.caps, conn);
    g.pieces.forEach((pc, i) => pc.number = i + 1);
    C.addLabels(g.pieces, g.caps, { depth: 0.6 });
    const files = g.pieces.map((pc, i) => ({ name: `fit_test_${'AB'[i]}.stl`, data: new Uint8Array(C.writeSTL(C.applyRotation(Float64Array.from(pc.p), C.bestOrientation(pc.p).r), 'fit test')) }));
    if (log.pins && log.pinSpec) files.push({ name: 'fit_test_pins.stl', data: new Uint8Array(C.writeSTL(C.pinPlate(log.pinSpec, log.pins, 100, 100), 'pins')) });
    files.push({ name: 'README.txt', data: `Fit test for ${conn.type} joints at ${conn.tolerance} mm clearance.\nPrint both blocks with the same settings as the real parts and push them together.\nToo tight: raise Fit clearance by 0.05-0.1 mm. Too loose: lower it.\n` });
    busy(false);
    await save(`fit_test_${conn.type}_${String(conn.tolerance).replace('.', '_')}mm.zip`, new Blob([T.zipBytes(files)], { type: 'application/zip' }), { tool: 'fittest' });
  } catch (e) { busy(false); console.error(e); toast('Could not make the fit test: ' + e.message); }
});

