      for (const f of [0.5, 1]) for (let i = 0; i < 48; i++) { const a = i / 48 * Math.PI * 2, b = (i + 1) / 48 * Math.PI * 2; pts.push(f * R * Math.cos(a), f * R * Math.sin(a), tn * f * R, f * R * Math.cos(b), f * R * Math.sin(b), tn * f * R); }
