    const parts = [{ p: r.p, name: 'Hollow model', color: css('--model'), tag: '#3d6be4', dir: [0, 0, 0] }];
    let plugs = null;
    if (r.plugs) { const bb = C.bbox(r.p); plugs = Float32Array.from(r.plugs); for (let i = 0; i < plugs.length; i += 3) { plugs[i] += bb.max[0] + 12; plugs[i + 1] += bb.min[1]; } parts.push({ p: plugs, name: `Plug${r.drains > 1 ? 's' : ''} \u00d7${r.drains}`, color: '#f2a541', tag: '#c2621d', dir: [1, 0, 0], spread: 0.3 }); }
