LEDES.necklace='One continuous articulated chain, curved to fit your plate. Add a separate snap clasp, pendant clip, or medallion blank.';
let ntPreviousSize=40;
let NT={result:null,worker:null,job:0,timer:null};window.GPNecklaceNT=NT;
function ntSwitch(t){if(t!=='necklace'&&NT.worker&&NT.building){NT.worker.terminate();NT.building=false;NT.key=null;busy(false);}if(['necklace','drawer','toolorg'].includes(t))$('explode').value=0;$('ntExportBar').hidden=t!=='necklace'||!NT.result;}
function ntOptions(){return {layout:$('ntLayout').value,style:$('ntStyle').value,profile:$('ntProfile').value,count:+$('ntCount').value,size:duNum('ntWidth'),width:duNum('ntWidth'),thickness:duNum('ntThickness'),clearance:duNum('ntClearance'),clasp:$('ntClasp').value,connector:$('ntConnector').value,pendantPosition:$('ntPendantPosition').value,pendantLink:+$('ntPendantLink').value,medallion:$('ntConnector').value==='none'?'none':$('ntMedallion').value,connectorInner:duNum('ntConnectorInner'),connectorWire:duNum('ntConnectorWire'),connectorThroat:duNum('ntConnectorThroat'),connectorClearance:duNum('ntConnectorClearance'),medallionWidth:duNum('ntMedallionWidth'),medallionThickness:duNum('ntMedallionThickness'),medallionHole:duNum('ntMedallionHole'),bed:(()=>{const o=$('ntBed').selectedOptions[0];if(o&&(o.value==='custom'||o.dataset.custom))return bed()[0];return +o.value||256;})(),preset:(()=>{const o=$('ntBed').selectedOptions[0];return (o&&(o.value==='custom'||o.dataset.custom))?'custom':(o.dataset.bambu||'A1');})()};}
function ntGenerate(){
 if(S.tool!=='necklace')return;const options=ntOptions(),key=JSON.stringify(options);if(NT.key===key&&(NT.result||NT.building)){if(NT.result)ntShow();return;}NT.key=key;NT.building=true;
 // Never blank: the last good chain stays on screen (downloads paused) until the new size builds or a clear reason is shown.
 NT.pending=true;$('ntDownload').disabled=$('nt3mf').disabled=true;$('ntError').textContent='';$('ntFit').hidden=true;$('ntStatus').textContent='Building smooth links and checking clearances\u2026';busy(true,'Generating necklace and validating the linked layout\u2026');
 if(NT.worker)NT.worker.terminate();const job=++NT.job;
 const urls=['earcut','clipper','core','tools','necklace'].map(id=>document.getElementById(id).src);
 const url=URL.createObjectURL(new Blob([`importScripts(${urls.map(u=>JSON.stringify(u)).join(',')});onmessage=e=>{try{postMessage({result:GPNecklace.build(e.data)})}catch(e){postMessage({error:e.message,capacity:e.capacity,code:e.code})}}`],{type:'text/javascript'}));
 const w=NT.worker=new Worker(url);URL.revokeObjectURL(url);
 const fail=(error,capacity)=>{if(job!==NT.job)return;NT.building=false;NT.pending=false;NT.failed=true;busy(false);NT.key=null;
  const keep=!!NT.result;
  // Nothing on screen yet (first open, or a smaller saved printer): build the longest chain that fits instead of an empty plate.
  if(!keep&&capacity>=4&&!NT.autoFit){NT.autoFit=true;NT.autoNote=`Requested ${+$('ntCount').value} links; ${capacity} fit this plate at this size, so the preview shows ${capacity}.`;$('ntCount').value=$('ntCountRange').value=capacity;w.terminate();ntGenerate();return;}$('ntError').textContent=error+(keep?' The preview still shows the last chain that fit; downloads are paused until this size builds.':'');
  if(capacity>=2){$('ntFit').textContent=`Use ${capacity} links at this size (fits this plate)`;$('ntFit').hidden=false;$('ntFit').onclick=()=>{$('ntCount').value=$('ntCountRange').value=capacity;ntGenerate();};}
  $('ntStatus').textContent=keep?'Showing the last chain that fit. Pick fewer links, smaller links or a bigger plate.':'Adjust the settings and generate again.';
  if(keep){$('ntExportBar').hidden=false;$('ntDownload').disabled=$('nt3mf').disabled=true;$('ntExportTitle').textContent=capacity>=2?`This size doesn't fit: max ${capacity} links. Showing the last chain that fit.`:'This size can\'t be built. Showing the last chain that fit.';}else clearOut();
  window.GPNecklaceState={failed:true,error,capacity,kept:keep};w.terminate();};
 w.onerror=e=>fail(e.message||'Could not build the chain.');
 w.onmessage=e=>{if(job!==NT.job)return;w.terminate();NT.building=false;if(e.data.error)return fail(e.data.error,e.data.capacity);if(S.tool!=='necklace'){busy(false);return;}
  NT.pending=false;NT.failed=false;NT.autoFit=true;NT.result=e.data.result;window.GPNecklaceState={failed:false,count:e.data.result.count};NT.projectId=newProjectId();window.GPNewResult=NT.result;const r=NT.result;
  duSet('ntLength',r.length);$('ntCount').value=$('ntCountRange').value=r.count;
  // The builder may thin the wire so small links still interlock; show the value actually used.
  if(r.spec?.thickness&&Math.abs(r.spec.thickness-duNum('ntThickness'))>.05){duSet('ntThickness',r.spec.thickness);}
  if(r.notes?.length)$('ntError').textContent='';
  $('ntPlate').innerHTML=r.plates.map((p,i)=>`<option value="${i}">${i===0?`Continuous chain \u00b7 ${r.count} closed links`:`Assembly accessories \u00b7 ${p.length} separate parts`}</option>`).join('');

  ntShow();busy(false);
 };w.postMessage(options);
}
function ntStatus(r){const a=r.assembly;$('ntStatus').textContent=`${r.count} closed links \u00b7 ${duText(r.length)} nominal laid-straight length \u00b7 one continuous ${r.layout.replace('continuous ','')} chain. These settings fit up to ${r.perPlate} links on the selected plate. Geometry checks: all ${r.count-1} neighbor pairs interlocked; all-pair minimum separation \u2265 ${duText(r.validation.minGap,true)}. Release, movement, flex, and retention have not been physically tested.${r.notes?.length?' '+r.notes.join(' '):''}`;
 $('ntAssembly').textContent=[a.clasp==='toggle'?`Included separately: toggle clasp \u00b7 ring (${duText(a.toggle.ringInner)} opening) and bar (${duText(a.toggle.barLength)} long), each with a C-snap loop (inner opening ${duText(a.endInner)}). Snap one loop onto each closed end link; pass the bar through the ring to close.`:a.clasp==='snap'?`Included separately: round C-snap end clasp (inner opening ${duText(a.endInner)}). Attach to both closed end links.`:'No end clasp included; use your own clasp.',a.connector!=='none'?`${a.connector==='oval'?'Oval':'Round'} C-snap pendant clip (inner opening ${duText(a.inner)}, wire ${duText(a.wire)}, throat ${duText(a.throat)}); assemble on highlighted link ${a.target}.`: 'No pendant connector included.',a.medallion?`${a.medallion.shape==='oval'?'Oval':'Round'} blank: ${duText(a.medallion.width)} \u00d7 ${duText(a.medallion.height)} \u00d7 ${duText(a.medallion.thickness)}, hole ${duText(a.medallion.hole)}. Clip through the hole after printing; not fused.`:'',r.accessoryPlate!==null?'Separate assembly accessories have their own labeled preview / export plate\u2014not another chain section.':''].filter(Boolean).join(' ');
}
function ntFitSample(r){const ids=r.chainIndices;let bestStart=0,bestTurn=-1;for(let i=0;i<=ids.length-6;i++){let turn=0;for(let j=i+1;j<i+6;j++){let d=r.parts[ids[j]].heading-r.parts[ids[j-1]].heading;turn+=Math.abs(Math.atan2(Math.sin(d),Math.cos(d)));}if(turn>bestTurn){bestTurn=turn;bestStart=i;}}return ids.slice(bestStart,bestStart+Math.min(6,ids.length));}
function ntInstructions(r,sample){const a=r.assembly;return `Expressarte necklace \u2014 dimensions in mm
${r.count} closed links; nominal laid-straight length ${r.length} mm.${r.spec.profile?` Link cut: ${({diamond:'diamond-cut table with beveled facets',crowned:'crowned top',flat:'classic flat shave'})[r.spec.profile]}; flat printing feet.`:''}\nOverall link length ${r.spec.size||2*(r.spec.a+r.spec.r)} mm; width ${r.spec.width} mm; wire ${r.spec.thickness} mm; requested clearance ${r.spec.clearance} mm.\nPlate: ${r.preset||r.bed}, ${r.bed} mm; ${r.layout}.
ONE continuous mechanically linked chain on the chain plate; it is not a rigid fused solid.
${r.validation.neighbors.length} consecutive pairs checked for linking number \u00b11; ${r.validation.checkedPairs} pairs checked for conservative swept-envelope separation >= ${r.validation.minGap.toFixed(3)} mm.
These are geometry checks, NOT physical print, movement, strength, flex, or retention tests.
Load each named production plate file separately, not stacked on top of the other plate.\nKeep all supplied chain-shell positions. Do NOT arrange individual shells.
The assembly-accessory plate, if present, is intentionally separate; it is NOT another chain section.
${a.clasp==='toggle'?`End clasp: separate toggle clasp. Ring piece (opening ${a.toggle.ringInner.toFixed(1)} mm) and bar piece (${a.toggle.barLength.toFixed(1)} mm long), ${a.toggle.thickness.toFixed(1)} mm thick, each with a C-snap loop (inner opening ${a.endInner.toFixed(2)} mm). Flex one loop onto each closed end link; pass the bar through the ring to close. Not a lobster clasp; test fit and retention.`:a.clasp==='snap'?`End clasp: separate round flexible C-snap; inner opening ${a.endInner.toFixed(2)} mm. Flex the open throat over BOTH closed end links after printing. It has no latch and is not a lobster clasp.`:'No clasp included. Supply your own clasp for the two closed end links.'}
${a.connector!=='none'?`Pendant connector: separate ${a.connector} C-snap bail; inner opening ${a.inner} mm; wire ${a.wire} mm; throat ${a.throat} mm; assembly clearance ${a.clearance} mm. Flex it onto chain link ${a.target} (1-based; highlighted teal). The center link is the bottom when worn, not the center of the packed plate. ${a.medallion?`Medallion blank: ${a.medallion.shape}, ${a.medallion.width} x ${a.medallion.height} x ${a.medallion.thickness} mm; hole ${a.medallion.hole} mm; top web ${a.medallion.web} mm. Thread the same clip through its hole after printing. Blank and clip are not fused; pendant remains removable.`:'No medallion blank included. Check your own pendant hole against the wire + 2 x clearance, and ensure its retained material is thicker than the open throat.'}`:'No pendant clip or medallion included.'}
OPTIONAL_6_LINK_FIT_TEST contains existing contiguous links ${sample.map(i=>i+1).join(', ')} from the tightest available turn. It is a standalone optional sample, NOT another production chain section. Print it by itself; do NOT import it on the full-chain plate because it intentionally duplicates six links. Test this before printing the full chain.
Start with 0.16\u20130.20 mm layers, dry filament, and a clean plate. Inspect gaps, overhangs, and supports in your slicer; no support-free / printability guarantee is implied.
C-snaps rely on elastic flex and a throat smaller than the minimum shaved link section (${r.validation.minMaterialSection.toFixed(2)} mm); there is no closing latch. PETG is a starting point, not a retention guarantee. Test assembly, flex, and accidental release. Do not force a brittle print.
Decorative only; not load-bearing; keep small parts away from children.
`;}

function ntShow(){const r=NT.result;if(!r)return;ntStatus(r);if(NT.autoNote){$('ntStatus').textContent=NT.autoNote+' '+$('ntStatus').textContent;NT.autoNote='';}window.GPNewResult=r;const ids=r.plates[+$('ntPlate').value||0],parts=ids.map(i=>r.parts[i]);
 const box=C.bbox(T.concat(parts.map(p=>p.p))),shift=[-(box.min[0]+box.max[0])/2,-(box.min[1]+box.max[1])/2,0];
 const shown=parts.map(pt=>({...pt,p:ntTranslate(pt.p,shift)}));
 showOut('necklace',T.concat(shown.map(pt=>pt.p)),'cuban_link_necklace',null,[stat(`${r.count}`,'links'),stat(duText(r.length),'laid-straight length'),stat(`${r.perPlate}`,'single-chain capacity'),stat(`${r.plates.length}`,'build plates')],'Cuban link necklace',shown);
 OUT.projectId=NT.projectId||(NT.projectId=newProjectId());$('outDl').textContent='Download necklace (.zip)';$('outSplit').hidden=true;$('ntExportTitle').textContent='Your necklace is ready';$('ntDownload').textContent='Download necklace (.zip)';$('ntDownload').disabled=$('nt3mf').disabled=false;$('ntExportBar').querySelector('small').textContent='One continuous chain + labeled assembly parts + optional 6-link test';$('ntExportBar').hidden=false;ntFinish(shown);
}
// Preview-only jewelry finish: smooth vertex normals (sharp facet creases kept) and polished metal with a studio reflection.
let ntMetal=null;
function ntSmoothGeometry(p,crease=38){const n=p.length/9,key=(i)=>`${Math.round(p[i]*1e4)},${Math.round(p[i+1]*1e4)},${Math.round(p[i+2]*1e4)}`,fn=new Float32Array(n*3),map=new Map(),ids=new Int32Array(n*3);
 for(let t=0;t<n;t++){const o=t*9,ax=p[o+3]-p[o],ay=p[o+4]-p[o+1],az=p[o+5]-p[o+2],bx=p[o+6]-p[o],by=p[o+7]-p[o+1],bz=p[o+8]-p[o+2];let x=ay*bz-az*by,y=az*bx-ax*bz,z=ax*by-ay*bx;const l=Math.hypot(x,y,z)||1;fn[t*3]=x/l;fn[t*3+1]=y/l;fn[t*3+2]=z/l;for(let k=0;k<3;k++){const kk=key(o+k*3);let v=map.get(kk);if(v===undefined){v=map.size;map.set(kk,v);}ids[t*3+k]=v;}}
 const lists=Array.from({length:map.size},()=>[]);for(let t=0;t<n;t++)for(let k=0;k<3;k++)lists[ids[t*3+k]].push(t);
 const cos=Math.cos(crease*Math.PI/180),normals=new Float32Array(n*9);
 for(let t=0;t<n;t++)for(let k=0;k<3;k++){let x=0,y=0,z=0;for(const u of lists[ids[t*3+k]]){const d=fn[t*3]*fn[u*3]+fn[t*3+1]*fn[u*3+1]+fn[t*3+2]*fn[u*3+2];if(d>=cos){x+=fn[u*3];y+=fn[u*3+1];z+=fn[u*3+2];}}const l=Math.hypot(x,y,z)||1;normals.set([x/l,y/l,z/l],t*9+k*3);}
 const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(Float32Array.from(p),3));g.setAttribute('normal',new THREE.BufferAttribute(normals,3));return g;}
function ntFinish(shown){const finish=$('ntFinish')?.value||'gold';if(finish==='print'||!outMesh)return;
 if(!ntMetal){let env=null;if(THREE.RoomEnvironment){const pm=new THREE.PMREMGenerator(renderer),room=new THREE.RoomEnvironment();env=pm.fromScene(room,.03).texture;pm.dispose();}ntMetal={env,cache:new Map()};}
 const tone={gold:['#e2b456','#f0c86a'],silver:['#d9dde3','#eef1f5'],rose:['#d8987c','#e8ad92']}[finish]||['#e2b456','#f0c86a'];
 const meshes=outMesh.isMesh?[outMesh]:outMesh.children;meshes.forEach((m,i)=>{const pt=shown[m.userData.i??i];if(!pt||!m.isMesh)return;const teal=pt.color==='#58b8ba'&&pt.kind==='chain';
  let g=ntMetal.cache.get(pt.p);if(!g){g=ntSmoothGeometry(pt.p);if(ntMetal.cache.size>400)ntMetal.cache.clear();ntMetal.cache.set(pt.p,g);}m.geometry.dispose();m.geometry=g;m.userData.ntShared=true;
  m.material.dispose?.();m.material=new THREE.MeshStandardMaterial({color:teal?'#58b8ba':tone[(pt.kind==='chain'?i:0)%2],metalness:teal?.2:1,roughness:pt.kind==='medallion'?.32:.22,envMap:ntMetal.env,envMapIntensity:1.25});});
 window.GPNecklaceFinish={finish,meshes:meshes.length,metal:meshes.filter(m=>m.material?.metalness===1).length,smooth:meshes.every(m=>!!m.geometry.attributes.normal)};updateScene?.();}
async function ntExport(kind){
 const r=NT.result;if(!r||S.tool!=='necklace')return;
 const req={tool:'necklace',projectId:OUT.projectId,label:'Cuban link necklace',multi3mf:kind==='3mf'};
 // Gate before creating a large archive; no new entitlement path or bypass.
 if(window.BSAccount&&!await BSAccount.gate(req))return;
 busy(true,'Preparing necklace download\u2026');await new Promise(resolve=>setTimeout(resolve,30));
 try{
 const files=[];
 for(let k=0;k<r.plates.length;k++){
  const pts=r.plates[k].map(i=>r.parts[i]),name=k===0?'necklace_continuous_chain':'necklace_assembly_accessories';
  // One build object per linked plate prevents slicer auto-arrange from unlinking the chain.
  const p=T.concat(pts.map(pt=>pt.p));
  if(kind==='stl')files.push({name:name+'.stl',data:new Uint8Array(C.writeSTL(p,name))});
  files.push({name:name+'.3mf',data:T.threeMF([{name,p}],{title:name,plates:[[0]],bambu:r.preset||(r.bed===180?'A1 mini':'A1')})});
 }
 const sample=ntFitSample(r),testName='OPTIONAL_6_LINK_FIT_TEST',testMesh=T.concat(sample.map(i=>r.parts[i].p));
 if(kind==='stl')files.push({name:testName+'.stl',data:new Uint8Array(C.writeSTL(testMesh,testName))});
 files.push({name:testName+'.3mf',data:T.threeMF([{name:testName,p:testMesh}],{title:testName,plates:[[0]],bambu:r.preset||(r.bed===180?'A1 mini':'A1')})});
 files.push({name:'PRINT_FIRST.txt',data:ntInstructions(r,sample)});
 files.push({name:'GEOMETRY_CHECKS.json',data:JSON.stringify({chainLinks:r.count,mechanicalChainComponents:1,closedSolidLinks:r.count,spec:r.spec,bed:r.bed,preset:r.preset,layout:r.layout,capacity:r.perPlate,validation:r.validation,assembly:r.assembly,optionalTestLinks:sample.map(i=>i+1),links:r.chainIndices.map(i=>({number:i+1,center:r.parts[i].center,heading:r.parts[i].heading,core:r.parts[i].curve}))})});
 await save('gigaprint_necklace'+(kind==='3mf'?'_3mf':'')+'.zip',new Blob([T.zipBytes(files)],{type:'application/zip'}));
 }catch(e){toast(e.message);}finally{busy(false);}
}
$('ntDownload').onclick=()=>['drawer','toolorg'].includes(S.tool)?hoExport('stl'):ntExport('stl');$('nt3mf').onclick=()=>['drawer','toolorg'].includes(S.tool)?hoExport('3mf'):ntExport('3mf');$('ntMake').onclick=ntGenerate;$('ntPlate').onchange=ntShow;
$('ntTest').onclick=()=>{$('ntCount').value=$('ntCountRange').value=6;$('ntPendantPosition').value='center';ntAccessoryFields();ntGenerate();};
function ntSchedule(){clearTimeout(NT.timer);NT.timer=setTimeout(ntGenerate,250);}
for(const id of ['Count','Width','Thickness','Clearance']){const num=$('nt'+id),range=$('nt'+id+'Range');for(const el of [num,range])el.addEventListener('input',()=>{if(id==='Width'&&$('ntStyle').value==='cuban'){const next=duNum(el.id);if(next>=16&&ntPreviousSize){const wire=Math.round(duNum('ntThickness')*next/ntPreviousSize*10)/10;duSet('ntThickness',Math.max(1.6,Math.min(16,wire)));ntPreviousSize=next;}}if(id==='Count'){if(el===num)range.value=num.value;else num.value=range.value;}ntSchedule();});num.addEventListener('change',ntSchedule);}
$('ntStyle').addEventListener('change',()=>{const cuban=$('ntStyle').value==='cuban';$('ntProfileLabel').hidden=!cuban;$('ntLayoutLabel').hidden=!cuban;duBounds('ntWidth',cuban?16:10,cuban?70:40,cuban?.2:.5);duBounds('ntThickness',1.6,cuban?16:6,.1);duLabel('ntSizeLabel',cuban?'Link size (overall length, mm)':'Link width (mm)');duSet('ntWidth',cuban?40:18);duSet('ntThickness',cuban?9.3:3);ntPreviousSize=duNum('ntWidth');ntSchedule();});
function ntAccessoryFields(){$('ntPendantFields').hidden=$('ntConnector').value==='none';$('ntPendantLinkLabel').hidden=$('ntPendantPosition').value!=='custom';$('ntMedallionFields').hidden=$('ntMedallion').value==='none';}
for(const id of ['ntConnector','ntPendantPosition','ntMedallion'])$(id).addEventListener('change',ntAccessoryFields);
for(const id of ['ntLayout','ntClasp','ntBed','ntConnector','ntPendantPosition','ntMedallion','ntProfile'])$(id).addEventListener('change',ntSchedule);$('ntFinish').addEventListener('change',()=>{if(NT.result)ntShow();});
for(const id of ['ntPendantLink','ntConnectorInner','ntConnectorWire','ntConnectorThroat','ntConnectorClearance','ntMedallionWidth','ntMedallionThickness','ntMedallionHole'])$(id).addEventListener('change',ntSchedule);
$('ntLength').onchange=()=>{try{const s=GPNecklace.spec(ntOptions()),pitch=NT.result?.pitch||GPNecklace.solvePitch(s),n=Math.max(4,Math.round((duNum('ntLength')-2*(s.a+s.r))/pitch)+1);$('ntCount').value=$('ntCountRange').value=n;ntSchedule();}catch(e){$('ntError').textContent=e.message;}};
