// Home organization collection lands on the drawer organizer unless a specific tool hash is used.
const HOMEORG_ALIASES={homeorg:'drawer','home-organization':'drawer',homeorganization:'drawer'};

LEDES.drawer='Custom drawer bins and kitchen inserts: silverware trays, angled knife racks, herb trays and more. Select a bin and drag its blue edges; neighbors resize automatically.';
LEDES.toolorg='Precision bits, 1/4-inch bits and labeled socket holders, made to fit your workspace.';
let HO={result:null,tree:GPHomeOrg.mixedTree(),cells:[],selected:new Set(),cols:3,rows:3,colWeights:[1,1,1],rowWeights:[1,1,1],heightFull:true,preset:'mixed',past:[],future:[],notice:'',job:0};
function hoKitchenControls(reset=false){const kind=$('hoKitchenKind').value;$('hoKitchenCountLabel').textContent=kind==='spice'||kind==='herb'?'Jars per row':kind==='knives'?'Blade slots':kind==='small'?'Small bins per row':kind==='silverwareDrawer'?'Cutlery + utensil lanes':'Main utensil lanes';$('hoKitchenCount').min=kind==='silverware'||kind==='silverwareDrawer'?4:1;$('hoKitchenCount').max=kind==='herb'?12:8;$('hoKitchenRows').max=kind==='herb'?8:6;for(const el of document.querySelectorAll('[data-kitchen-for]'))el.hidden=!el.dataset.kitchenFor.split(' ').includes(kind);duLabel('hoKitchenLengthLabel',kind==='spice'||kind==='herb'?'Full jar length (mm)':kind==='knives'?'Blade-slot length (mm)':kind==='silverwareDrawer'?'Auto-fit utensil length (mm)':'Usable utensil length (mm)');if(reset){$('hoKitchenCount').value=kind==='spice'?6:kind==='herb'?6:kind==='utensils'?3:kind==='small'?4:kind==='silverwareDrawer'?4:kind==='knives'?6:5;$('hoKitchenRows').value=kind==='herb'?4:2;duSet('hoKitchenLength',kind==='spice'||kind==='herb'?100:kind==='knives'?180:220);if(kind==='knives'&&$('hoKnifePreset'))$('hoKnifePreset').value='chef';}$('hoKitchenSafety').hidden=kind!=='knives'&&!HO.cells.some(c=>c.kitchen?.kind==='knife');}
function hoKitchenSummary(){const list=$('hoKitchenSummary');list.replaceChildren();for(const [i,c]of HO.cells.entries())if(c.kitchen){const li=document.createElement('li');li.textContent=`${i+1}. ${c.kitchen.label}${c.kitchen.kind==='spice'?` \u00b7 jar ${duText(c.kitchen.diameter)} diameter \u00d7 ${duText(c.kitchen.length)} long`:c.kitchen.kind==='herb'?` \u00b7 ${c.kitchen.count} jars \u00b7 ${c.kitchen.cols}\u00d7${c.kitchen.rows} \u00b7 ${c.kitchen.angle}\u00b0 tiers`:c.kitchen.kind==='knife'?` \u00b7 ${c.kitchen.count} angled slots \u00b7 ${duText(c.kitchen.slot)} wide \u00b7 ${c.kitchen.angle}\u00b0 \u00b7 ${duText(c.kitchen.length)} long`:c.kitchen.usableLength?` \u00b7 measured length ${duText(c.kitchen.usableLength)}`:''}${c.kitchen.wells?` \u00b7 ${c.kitchen.wellEnds==='both'?'pick-out wells at both ends':c.kitchen.wellEnds+' pick-out well'} ${duText(c.kitchen.wellWidth)} \u00d7 ${duText(c.kitchen.wellLength)}, floor raised ${duText(c.kitchen.lift)}${c.kitchen.wellThrough?', open through the floor':''}`:''}`;list.append(li);}hoKitchenControls();}
function hoKitchenApply(){try{const o=hoOptions(true),kind=$('hoKitchenKind').value,knifePreset=$('hoKnifePreset')?.value||'custom',tree=GPHomeOrg.kitchenPreset({...o,kind,count:+$('hoKitchenCount').value,rows:+$('hoKitchenRows').value,length:duNum('hoKitchenLength'),laneWidth:duNum('hoKitchenWidth'),diameter:duNum('hoJarDiameter'),spacing:duNum('hoKnifeSpacing'),slot:duNum('hoKnifeSlot'),angle:+($('hoKnifeAngle')?.value||30),knifePreset:knifePreset==='custom'?undefined:knifePreset,tierAngle:+($('hoHerbAngle')?.value||30),lip:+($('hoHerbLip')?.value||10),autofit:kind==='herb'?!!$('hoHerbAutofit')?.checked:undefined,scoops:$('hoKitchenScoops').checked,scoopDepth:duNum('hoKitchenScoopDepth'),scoopWidth:duNum('hoKitchenScoopWidth'),wells:$('hoKitchenWells').checked,wellEnds:$('hoKitchenWellEnds').value,wellWidth:duNum('hoKitchenWellWidth'),wellLength:duNum('hoKitchenWellLength'),wellOffset:duNum('hoKitchenWellOffset'),lift:duNum('hoKitchenLift'),wellThrough:$('hoKitchenWellThrough').checked,previous:HO.cells});GPHomeOrg.drawer({...o,cells:GPHomeOrg.treeCells(tree)});hoReplace(tree,+$('hoKitchenCount').value,+$('hoKitchenRows').value,'custom','kitchen layout');$('hoKitchenResult').classList.remove('ho-kitchen-error');$('hoKitchenResult').textContent='Kitchen layout applied. Matching slots kept their overrides; global defaults are unchanged. Undo layout restores the previous kit.';}catch(e){$('hoKitchenResult').classList.add('ho-kitchen-error');$('hoKitchenResult').textContent=e.message;}}
function hoRoomPlan(){const r=GPHomeOrg.ROOMS[$('hoRoomKind').value],list=$('hoRoomPlan');list.replaceChildren();r.rows.forEach((row,i)=>{const li=document.createElement('li');li.textContent=`Row ${i+1}: `+row.cells.map(c=>c.ins?`${c.label} (${GPInserts.byId[c.ins.id].name.toLowerCase()})`:`${c.label}`).join(' \u00b7 ');list.appendChild(li);});}
