(function hoFurnitureInit(){const sel=$('hoFurniture');if(!sel||!window.GPHomeOrg?.DRAWER_PRESETS)return;
 for(const pr of GPHomeOrg.DRAWER_PRESETS){if(pr.id==='custom')continue;const o=document.createElement('option');o.value=pr.id;o.textContent=pr.name;sel.append(o);}
 sel.onchange=()=>{const pr=GPHomeOrg.DRAWER_PRESETS.find(p=>p.id===sel.value);$('hoFurnitureNote').textContent=pr?.note?pr.note+' Always re-measure before a full print.':'Pick a common drawer size to fill width, depth and height. Names are generic; always re-measure your own drawer before a full print run.';if(!pr||pr.width==null)return;duSet('hoWidth',pr.width);duSet('hoDepth',pr.depth);duSet('hoHeight',pr.height);HO.heightFull=true;hoSchedule();};})();

