// Bathroom drawer: toothbrush cradles for the chosen model, blade bank, swabs, toothpaste and small items, fitted to the drawer.
function hoBathFillSelects(){const fill=(id,list)=>{const el=$(id);if(!el||el.options.length)return;list.forEach((x,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=x.name;el.append(o);});};fill('hoBathBrush',GPInserts.BRUSHES);fill('hoInsModel',GPInserts.BRUSHES);fill('hoBathBlade',GPInserts.BLADES);fill('hoInsBlade',GPInserts.BLADES);}
hoBathFillSelects();
function hoBathApply(opts={}){const res=$('hoBathResult');try{
 hoBathFillSelects();const o=hoOptions(true),brushModel=+($('hoBathBrush')?.value||0),brushCount=+($('hoBathCount')?.value||2),blade=+($('hoBathBlade')?.value||0);
 const tree=GPHomeOrg.bathroomDrawerPreset({...o,brushModel,brushCount,blade});
 GPHomeOrg.drawer({...o,cells:GPHomeOrg.treeCells(tree)});
 const cells=GPHomeOrg.treeCells(tree),b=tree.bathroom||{};
 hoReplace(tree,Math.max(2,cells.length),2,'custom','bathroom drawer');
 const text=`Bathroom drawer \u00b7 ${b.count} \u00d7 ${b.modelName} cradles \u00b7 ${cells.length} bins${cells.some(c=>c.insert?.id==='bladebank')?' \u00b7 blade bank':''} \u00b7 cotton swabs ${b.upright?'upright':'lying flat (drawer under 80 mm)'} \u00b7 fitted to ${duDims([o.width,o.depth])}.`;
 if(res){res.classList.remove('ho-kitchen-error');res.textContent=text;}
 if(opts.scroll!==false)$('hoBathCta')?.scrollIntoView({behavior:'smooth',block:'nearest'});
}catch(e){if(res){res.classList.add('ho-kitchen-error');res.textContent=e.message;}}}
