// The blade bank on its own: body + snap lid on one plate, no drawer bins.
async function hoBankDownload(){const sel=hoInsertCells(),ins=sel[0]?.c.insert;if(!ins||ins.id!=='bladebank')return;
 busy(true,'Preparing the blade bank\u2026');await new Promise(r=>setTimeout(r,20));try{
  const o=hoOptions(true),info=hoBinPart(sel[0].i)?.insert?.bank,H=info?.height||(+ins.pegH>0?+ins.pegH:60),bk=GPInserts.bladeBank(+(ins.blade||0),H);
  const parts=[{name:`blade_bank_body_${bk.blade.id}_${bk.W.toFixed(1)}x${bk.D.toFixed(1)}x${bk.body.h.toFixed(1)}mm`,local:bk.body.local,w:bk.W,d:bk.D,h:bk.body.h},{name:`blade_bank_lid_${bk.blade.id}_${bk.W.toFixed(1)}x${bk.D.toFixed(1)}x${bk.lid.h.toFixed(1)}mm`,local:bk.lid.local,w:bk.W,d:bk.D,h:bk.lid.h}];
  const L=GPHomeOrg.pack(parts,o.bedY?[o.bed,o.bedY]:o.bed,o.preset,o.bedZ),bambu=T.BAMBU_PRESETS[o.preset]?o.preset:'A1';
  const objects=L.packed.map(q=>({name:q.name,p:q.p})),files=parts.map(p=>({name:p.name+'.stl',data:new Uint8Array(C.writeSTL(p.local,p.name))}));
  files.push({name:'blade_bank.3mf',data:T.threeMF(objects,{title:'Expressarte blade bank',plates:L.plates.map(ids=>ids),bambu})});
  files.push({name:'PRINTING.txt',data:`Expressarte blade bank \u00b7 ${bk.blade.name}\nSlot ${bk.blade.slot[0]} x ${bk.blade.slot[1]} mm \u00b7 outside ${bk.W.toFixed(1)} x ${bk.D.toFixed(1)} x ${bk.height.toFixed(1)} mm\n${bk.note}\n`});
  await save('gigaprint_blade_bank.zip',new Blob([T.zipBytes(files)],{type:'application/zip'}));
 }catch(e){toast(e.message);}finally{busy(false);}}
$('hoBankDownload')?.addEventListener('click',hoBankDownload);
function hoHerbPresetApply(){try{$('hoKitchenKind').value='herb';hoKitchenControls(true);if($('hoHerbAutofit'))$('hoHerbAutofit').checked=true;if($('hoHerbAngle')){$('hoHerbAngle').value=30;if($('hoHerbAngleRange'))$('hoHerbAngleRange').value=30;}if($('hoHerbLip'))$('hoHerbLip').value=10;if(hoNum('hoHeight')<95){duSet('hoHeight',95);if(hoNum('hoDefaultHeight')<88)duSet('hoDefaultHeight',88);}const o=hoOptions(true),tree=GPHomeOrg.herbTrayPreset({...o,diameter:duNum('hoJarDiameter'),length:duNum('hoKitchenLength'),tierAngle:+($('hoHerbAngle')?.value||30),lip:+($('hoHerbLip')?.value||10),targetJars:30});GPHomeOrg.drawer({...o,cells:GPHomeOrg.treeCells(tree)});const cell=GPHomeOrg.treeCells(tree)[0]?.kitchen;hoReplace(tree,cell?.cols||6,cell?.rows||4,'custom','herb tray');const msg=`Herb tray \u00b7 ${cell?.count||'?'} jars \u00b7 ${cell?.cols}\u00d7${cell?.rows} tiers at ${cell?.angle}\u00b0.`;$('hoKitchenResult').classList.remove('ho-kitchen-error');$('hoKitchenResult').textContent=msg;}catch(e){$('hoKitchenResult').classList.add('ho-kitchen-error');$('hoKitchenResult').textContent=e.message;}}
$('hoHerbPreset')?.addEventListener('click',hoHerbPresetApply);window.hoHerbPresetApply=hoHerbPresetApply;
function hoKnifeBlockPresetApply(){try{$('hoKitchenKind').value='knives';hoKitchenControls(true);if($('hoKnifePreset'))$('hoKnifePreset').value='mixed';if(hoNum('hoHeight')<60){duSet('hoHeight',70);if(hoNum('hoDefaultHeight')<50)duSet('hoDefaultHeight',55);}const p=GPHomeOrg.KNIFE_PRESETS.mixed;duSet('hoKitchenLength',Math.max(...p.lengths));duSet('hoKnifeSpacing',p.spacing);$('hoKnifeSlot').value=p.slot;if($('hoKnifeAngle')){$('hoKnifeAngle').value=p.angle;if($('hoKnifeAngleRange'))$('hoKnifeAngleRange').value=p.angle;}$('hoKitchenCount').value=p.lengths.length;const o=hoOptions(true),tree=GPHomeOrg.knifeBlockPreset({...o,knifePreset:'mixed',angle:p.angle});GPHomeOrg.drawer({...o,cells:GPHomeOrg.treeCells(tree)});const cells=GPHomeOrg.treeCells(tree),cell=cells[0]?.kitchen,binH=cells[0]?.bin?.height;if(binH&&hoNum('hoDefaultHeight')<binH)duSet('hoDefaultHeight',Math.round(binH));hoReplace(tree,1,1,'custom','knife block');$('hoKitchenResult').classList.remove('ho-kitchen-error');$('hoKitchenResult').textContent=`Knife block \u00b7 ${cell?.count||'?'} deep blade slots \u00b7 fills the drawer.`;}catch(e){$('hoKitchenResult').classList.add('ho-kitchen-error');$('hoKitchenResult').textContent=e.message;}}
