function hoNum(id){return duNum(id);}
// 42 mm grid unit mode: the layout is cols\u00d7rows whole units; every seam sits on a unit line.
function hoGridOn(){return !!($('hoGridBase')?.checked||$('hoGridBaseTop')?.checked);}
function hoUnitMode(){return hoGridOn()&&!!$('hoGridUnits')?.checked;}
function hoUnitCounts(){return {nx:Math.max(1,Math.min(60,Math.round(+$('hoGridCols')?.value||1))),ny:Math.max(1,Math.min(60,Math.round(+$('hoGridRows')?.value||1)))};}
function hoSpan(){if(hoUnitMode()){const u=hoUnitCounts();return {W:u.nx*42,D:u.ny*42,unit:42,nx:u.nx,ny:u.ny};}const c=hoNum('hoClearance');return {W:hoNum('hoWidth')-2*c,D:hoNum('hoDepth')-2*c,unit:0};}
function hoGridFitDrawer(){const f=GPHomeOrg.gridUnitFit(hoNum('hoWidth'),hoNum('hoDepth'));if($('hoGridCols'))$('hoGridCols').value=f.nx;if($('hoGridRows'))$('hoGridRows').value=f.ny;return f;}
function hoSyncCells(){HO.unitNote='';if(hoUnitMode()&&!HO.syncing){
 // 42 mm grid: seams round to whole units (never adds bins). A bin smaller than one unit merges into its neighbor;
 // that change is one Undo step and the note says so.
 const u=hoUnitCounts(),was=JSON.stringify(HO.tree),snap=GPHomeOrg.treeSnapUnits(HO.tree,u.nx,u.ny);
 if(JSON.stringify(HO.tree)!==was&&HO.committed){HO.syncing=true;try{hoCommit(snap.dropped?'merge bins smaller than a 42 mm unit':'snap to 42 mm units');}finally{HO.syncing=false;}}
 if(snap.dropped){HO.selected.clear();HO.notice=`Snapped the layout to whole 42 mm units; ${snap.dropped} bin${snap.dropped>1?'s were':' was'} smaller than one unit and merged into ${snap.dropped>1?'their':'its'} neighbors. Undo restores ${snap.dropped>1?'them':'it'}, or add units first.`;}}
 HO.cells=GPHomeOrg.treeCells(HO.tree).map(({path,...c})=>c);}
// Project history: every committed state is the whole drawer project (size, global settings, layout, per-bin
// settings, organizer objects and extras). A change is committed right away by hoRemember(), or after a short pause
// for typing and slider drags (hoCommitSoon), so one drag is one Undo step.
function hoSelectedIds(){const cells=GPHomeOrg.treeCells(HO.tree);return [...HO.selected].map(i=>cells[i]?.id).filter(id=>id!=null);}
function hoSnapshot(){hoCommitPending();return {...hpCollect(),selected:hoSelectedIds()};}
function hoStateKey(p=hpCollect()){return JSON.stringify(p);}
function hoCommit(label='change',key=null){clearTimeout(HO.commitTimer);HO.commitTimer=null;HO.pendingLabel=null;if(!HO.committed)return;const now=performance.now(),cur=hpCollect(),json=hoStateKey(cur),merge=key&&HO.historyKey===key&&(HO.drag||now-HO.historyTime<=600);HO.historyKey=key;HO.historyTime=now;if(json===HO.committedJson)return;if(!merge){HO.past.push({...HO.committed,label});if(HO.past.length>60)HO.past.shift();}HO.future=[];HO.committed={...cur,selected:hoSelectedIds()};HO.committedJson=json;if(typeof hoMergeControls==='function'&&$('hoUndo'))hoMergeControls();hpSchedule();}
function hoCommitSoon(label){if(!HO.committed)return;HO.pendingLabel=label||HO.pendingLabel||'change';clearTimeout(HO.commitTimer);HO.commitTimer=setTimeout(()=>{if(HO.pointerDown){hoCommitSoon(HO.pendingLabel);return;}hoCommit(HO.pendingLabel);},650);}
function hoCommitPending(){if(HO.commitTimer)hoCommit(HO.pendingLabel||'change');}
// The undo step keeps the selection from just before the change (e.g. the two bins that were merged).
function hoRemember(before,label,key){if(before&&HO.committed){const{selected,...rest}=before;if(hoStateKey(rest)===HO.committedJson)HO.committed={...HO.committed,selected};}hoCommit(label,key);}
function hoRestore(state){hpApply(state);const cells=GPHomeOrg.treeCells(HO.tree);HO.selected=new Set(cells.flatMap((c,i)=>(state.selected||[]).includes(c.id)?[i]:[]));}
function hoHistory(redo=false){hoCommitPending();const from=redo?HO.future:HO.past,to=redo?HO.past:HO.future;if(!from.length)return;const state=from.pop();to.push({...HO.committed,selected:hoSelectedIds(),label:state.label});hoRestore(state);HO.committed={...hpCollect(),selected:hoSelectedIds()};HO.committedJson=hoStateKey(hpCollect());HO.historyKey=null;HO.actionError=false;HO.notice=`${redo?'Redid':'Undid'} ${state.label}. Drawer size, layout, bin settings, objects and extras restored.`;hoGrid();hoGenerate();hpSchedule();}
function hoReplace(tree,cols,rows,preset,label){const before=hoSnapshot();HO.tree=tree;HO.cols=cols;HO.rows=rows;HO.preset=preset;HO.selected.clear();$('hoCols').value=cols;$('hoRows').value=rows;$('hoPreset').value=preset;hoRemember(before,label);HO.notice='';HO.actionError=false;hoGrid();hoGenerate();}
function hoReset(force){const cols=Math.max(1,Math.min(8,Math.round(hoNum('hoCols')||3))),rows=Math.max(1,Math.min(8,Math.round(hoNum('hoRows')||3)));if(force!==true&&cols===HO.cols&&rows===HO.rows)return;hoReplace(GPHomeOrg.treeGrid(rows,cols),cols,rows,'grid','grid reset');}
