  const cv=document.createElement('canvas');cv.width=W;cv.height=H;const cx=cv.getContext('2d',{willReadFrequently:true});cx.imageSmoothingQuality='high';cx.drawImage(im,0,0,W,H);const d=cx.getImageData(0,0,W,H),g=GPClicker.imageGray(d.data,W,H);
  HO.decoImg=GPLidDeco.addImage({name:f.name,gray:g.gray,alpha:g.transparent?g.alpha:null,w:W,h:H});$('hoDecoKind').value='image';hoDecoEdit(true);
