// ---------------------------------------------------------------- one-time announcements (signed-in users)
// Each launch gets an id; dismissing (or opening the tool) stores gp.announce.<id> in localStorage so it never shows
// again in this browser. To announce the next tool, change ANNOUNCE (id, tool, texts).
const ANNOUNCE = { id: '2026-11-multicolor', tool: 'mc' };
const annKey = id => 'gp.announce.' + id;
function annDismissed(id) { try { return localStorage.getItem(annKey(id)) === 'dismissed'; } catch (e) { return false; } }
function annSeen(tool) { if (tool === ANNOUNCE.tool) annDismiss(); }
function annDismiss() { try { localStorage.setItem(annKey(ANNOUNCE.id), 'dismissed'); } catch (e) {} $('announce').hidden = true; }
function annCheck() {
  const el = $('announce'); el.dataset.id = ANNOUNCE.id;
  const signedIn = !!(window.BSAccount && BSAccount.state && BSAccount.state.session);
  // home screen only, so it never covers a tool's controls or download buttons
  el.hidden = !(signedIn && !annDismissed(ANNOUNCE.id) && !$('home').hidden);
}
$('announceX').addEventListener('click', annDismiss);
$('announceGo').addEventListener('click', annDismiss);
document.addEventListener('keydown', e => { if (e.key === 'Escape' && !$('announce').hidden) annDismiss(); });
window.addEventListener('storage', e => { if (/^bs\./.test(e.key || '')) annCheck(); });
window.addEventListener('focus', annCheck);
Promise.resolve(window.BSAccount && BSAccount.state && BSAccount.state.ready).catch(() => {}).then(annCheck);
setTimeout(annCheck, 1500);
new MutationObserver(annCheck).observe($('home'), { attributes: true, attributeFilter: ['hidden'] });
window.GPAnnounce = { id: ANNOUNCE.id, check: annCheck, dismiss: annDismiss };
