    texture: BBX.tex, texScale: bbScaleFromSlider(), texDepth: BBX.tex === 'smooth' ? 0 : bbDepthFromSlider(), mount, keyholes: $('bbKeyN').value, tolerance: bbNum('bbTol', 0.2, 0, 0.8),
    lean: bbNum('bbLean', 10, 2, 25), standT: bbNum('bbStandT', 3.2, 2, 6), magnetD: bbNum('bbMagD', 8, 3, 25), magnetH: bbNum('bbMagH', 3, 1, 8), magnets: bbNum('bbMagN', 2, 1, 4),
    stripW: bbNum('bbStripW', 46, 15, 80), stripH: bbNum('bbStripH', 16, 8, 30), colors: bbChars().map((c, i) => BBX.colors[i] || BB.PALETTE[i % BB.PALETTE.length].hex),
