  const mounts = { stand: L.filter(l => l.stand).length + ' stands', keyhole: L.reduce((a, l) => a + l.pockets, 0) + ' keyhole slots', sawtooth: 'sawtooth recesses', strip: 'strip pads', magnet: L.reduce((a, l) => a + l.pockets, 0) + ' magnet pockets', none: 'flat backs' }[r.stats.mount] || '';
