  const D = BB.TEXTURES[BBX.tex];
  $('bbTexScaleOut').textContent = BBX.tex === 'smooth' ? '\u2013' : `${bbScaleFromSlider()} mm`;
  $('bbTexDepthOut').textContent = BBX.tex === 'smooth' ? '\u2013' : `${bbDepthFromSlider()} mm`;
  $('bbTexNote').textContent = D.note;
