document.querySelectorAll('input[name="bbFont"],input[name="bbMount"],input[name="bbView"]').forEach(r => r.addEventListener('change', () => { bbFields(); bbSchedule(); }));
$('printer').addEventListener('change', () => { if (S.tool === 'bubble') bbSchedule(); });
