window.GPBbView = () => ({ kind: OUT.kind, tool: S.tool, detail: BBX.res && BBX.res.detail, letters: BBX.res ? BBX.res.letters.map(l => l.ch) : [], meshes: outMesh ? (outMesh.isGroup ? outMesh.children.length : 1) : 0, colors: outMesh ? (outMesh.isGroup ? outMesh.children : [outMesh]).map(m => '#' + m.material.color.getHexString().toUpperCase()) : [], closed: BBX.res && BBX.res.closed, busy: BBX.busy || !!BBX.pending, stats: BBX.res && BBX.res.stats, warnings: BBX.res && BBX.res.warnings });
