  const why = r && r.gate ? r.gate : PD.gateInfo(o);
  const req = { tool: 'potsdrawer', projectId: OUT.projectId, label: pdT('Pots and pans drawer'), pegs: r ? r.stats.pegs : 0, lidRack: !!(o.lidRack && (!r || r.stats.lidRacks)), cradles: !!o.cradles, reasons: why.map(w => pdT(w)), extras: [] };
