const FGX = window.FGX;
Object.assign(FGX, { res: null, worker: null, job: 0, timer: 0, hdTimer: 0, busy: false, pending: null, exportWait: null, colors: { body: '#E8F1F5', accent: SplitCore.PASTELS.babyBlue }, preview: null,
  layout: null, sel: new Set(), past: [], future: [], msg: '', err: false });
const FR_MM = ['fgW', 'fgD', 'fgH', 'fgModH', 'fgBottleD', 'fgCupD', 'fgRim', 'fgWall', 'fgKeyClear'];
const FR_COLORS = { egg: '#d9a441', soda: '#d0503e', bottle: '#5b7f3a', condiment: '#c77b2b', cups: '#8a63c9', produce: '#3aa17e', deli: '#2f9fb3', butter: '#c9a227', stack: '#3b6fc4', turntable: '#b0607a', bin: '#5b7d91', empty: 'transparent' };
const FR_KEY = 'gp.fridge.v1';
