    b.title = `${fgT(T.name)} ${i + 1}` + (info && m.type !== 'empty' ? ` \u00b7 ${typeof duDims === 'function' ? duDims([info.w, info.d]) : info.w + ' \u00d7 ' + info.d + ' mm'}` : '') + (info && info.warn && info.warn.length ? ' \u00b7 ' + info.warn.join(' ') : '');
