  $('fgMerge').disabled = ids.length < 2; $('fgSplit').disabled = !ids.some(i => { const m = L.modules[i]; return m.c1 - m.c0 > 1 || m.r1 - m.r0 > 1; });
  $('fgFlat').disabled = !ids.some(i => L.modules[i].type !== 'bin'); $('fgClear').disabled = !ids.some(i => L.modules[i].type !== 'empty');
