function fgSetType(type, msg) { const ids = fgSelected(); if (!ids.length) return; const before = fgSnap(); for (const i of ids) { FGX.layout.modules[i].type = type; FGX.layout.modules[i].o = {}; } fgCommit(before, msg); }
