  const m = ids.length === 1 ? FGX.layout.modules[ids[0]] : null;
  step.hidden = !m || m.type === 'empty' || S.tool !== 'fridge';
  if (step.hidden) return;
  $('fgModTitle').textContent = `${FGG.TYPES[m.type].name} ${ids[0] + 1}`;
  for (const el of step.querySelectorAll('[data-fr]')) el.hidden = el.dataset.fr === 'h' ? ['egg', 'soda', 'bottle', 'turntable'].includes(m.type) : el.dataset.fr !== m.type;
