    if (info.bottles) n.push(info.bottles === 1 ? '1 bottle' : `${info.bottles} bottles`);
    if (info.sticks) n.push(`${info.sticks} sticks of butter`);
    if (info.cells) n.push(`${info.cells} cups`);
    if (info.diameter) n.push(`Platter ${len(info.diameter)} across`);
