  if (id === 'fgEggStack') o.stack = $('fgEggStack').checked;
  if (id === 'fgEggTrays') o.trays = Math.round(fgNum('fgEggTrays', 1, 1, 4));
  if (id === 'fgCan') o.can = $('fgCan').value;
  if (id === 'fgSlope') o.slope = fgNum('fgSlope', 5, 3, 10);
  if (id === 'fgLoader') o.loader = $('fgLoader').checked;
  if (id === 'fgBottleD') o.bottleD = fgNum('fgBottleD', 80, 50, 130);
  if (id === 'fgCupD') o.cupD = fgNum('fgCupD', 95, 40, 160);
