  const urls = ['earcut', 'clipper', 'core', 'tools', 'plates', 'c7bulb'].map(srcOf);
  const code = `importScripts(${urls.map(u => JSON.stringify(u)).join(',')});let R=null,RO=null;
const same=(a,b)=>JSON.stringify({...a,detail:0})===JSON.stringify({...b,detail:0});
onmessage=e=>{const d=e.data;try{
 if(d.type==='build'){R=GPC7Bulb.build(d.opts);RO=d.opts;
  const meshes=R.parts.map(m=>{
    const assembled=Float32Array.from(m.assembled||m.p);
    const local=m.local&&m.local!==m.assembled?Float32Array.from(m.local):null;
    return {name:m.name,kind:m.kind,color:m.color,pieceIndex:m.pieceIndex,dir:m.dir,spread:m.spread,p:assembled,local};
  });
  const plate=Float32Array.from(StudioTools.concat(meshes.map(q=>q.p)));
  const xfer=meshes.flatMap(m=>[m.p.buffer,...(m.local?[m.local.buffer]:[])]).concat([plate.buffer]);
  postMessage({job:d.job,type:'build',res:{meshes,plate,warnings:R.warnings,stats:R.stats,split:R.split,detail:d.opts.detail||'hd',filaments:R.filaments,options:R.options}},xfer);return;}
 if(d.type==='export'){if(!R||!RO||!same(RO,d.opts)){R=GPC7Bulb.build(d.opts);RO=d.opts;}
  const o={name:d.name,fileBase:d.fileBase,bambu:d.bambu,bed:d.opts.bed};const bytes=d.kind==='3mf'?GPC7Bulb.export3MF(R,o):StudioTools.zipBytes(GPC7Bulb.files(R,o));
  postMessage({job:d.job,type:'export',kind:d.kind,bytes},[bytes.buffer]);return;}
}catch(err){postMessage({job:d.job,type:d.type,error:err.message||String(err)});}};`;
  const url = URL.createObjectURL(new Blob([code], { type: 'text/javascript' }));
