window.SGX = window.SGX || {};
const SGX = window.SGX;
Object.assign(SGX, { res: null, worker: null, job: 0, timer: 0, hdTimer: 0, busy: false, pending: null, exportWait: null, colors: { base: SplitCore.PASTELS.cream, text: '#1A1A1A', border: SplitCore.PASTELS.babyBlue }, svg: null, svgName: '' });
function sgNum(id, d, lo, hi) { const v = parseFloat($(id).value); return Number.isFinite(v) ? Math.max(lo, Math.min(hi, v)) : d; }
