async function man(d){if(MF===null){MF=false;try{if(d.js&&typeof WebAssembly!=='undefined'){const mod=await import(d.js);const m=await mod.default({locateFile:()=>d.wasm});m.setup();MF=m;}}catch(e){MF=false;}}return MF||null;}
