Object.assign(HSX, { res: null, worker: null, workerOK: true, job: 0, timer: 0, busy: false, pending: null, exportWait: null, lastMsg: null, gb: null, colors: { body: '#2B2F33', bolts: '#E07A3A' }, openings: [] });
