    mount: $('hsMount').value, boardT: hsNum('hsBoardT', 6.4, 3, 20), screwD: hsNum('hsScrewD', 4, 2.5, 6),
    front: $('hsFront').value, retain: $('hsRetain').value, material: $('hsMat').value,
