    for (let y = 0; y < 80; y++) for (let x = 0; x < 80; x++) { const i = Math.floor((x - ox) * sc), j = Math.floor((y - oy) * sc), q = (y * 80 + x) * 4; const on = i >= 0 && j >= 0 && i < m.w && j < m.h && m.d[j * m.w + i] > 0.5; img.data[q] = on ? 40 : 247; img.data[q + 1] = on ? 42 : 241; img.data[q + 2] = on ? 48 : 227; img.data[q + 3] = 255; }
