    let M = null; try { M = await loadManifold(); } catch (e) { M = null; }
    const r = CSA.build(o, M), file = o.qty > 1 ? 'custom_coasters' : 'custom_coaster', eo = { name: 'Custom coaster', fileBase: file, bambu: o.bambu };
    const bytes = kind === '3mf' ? CSA.export3MF(r, eo) : T.zipBytes(CSA.files(r, eo));
    await save(`${file}.${kind === '3mf' ? '3mf' : 'zip'}`, new Blob([bytes], { type: kind === '3mf' ? 'model/3mf' : 'application/zip' }));
