// ---- export (gated by the backer entitlement)
async function cuExport(kind) {
  if (S.tool !== 'cubbies') return;
  const o = cuOpts();
  const req = Object.assign({ tool: 'cubbies', projectId: OUT.projectId, label: 'Form-fit cubbies' }, CUA.gateInfo(o));
  if (window.BSAccount && !await BSAccount.gate(req)) return;
  busy(true, 'Building the cubby files\u2026');
  await new Promise(res => setTimeout(res, 30));
  try {
    const M = await loadManifold(), r = CUA.build(o, M);
    const file = 'form_fit_cubbies', eo = { name: 'Form-fit cubbies', fileBase: file, bambu: o.bambu };
    const bytes = kind === '3mf' ? CUA.export3MF(r, eo) : T.zipBytes(CUA.files(r, eo));
    await save(`${file}.${kind === '3mf' ? '3mf' : 'zip'}`, new Blob([bytes], { type: kind === '3mf' ? 'model/3mf' : 'application/zip' }));
  } catch (e) { toast(e.message || String(e)); } finally { busy(false); }
}
// ---- colors
