Object.assign(PCX, { res: null, worker: null, workerOK: true, job: 0, timer: 0, busy: false, pending: null, exportWait: null, imgData: null, image: null, imageName: '', printParts: null, showPhone: true,
  colors: { case: '#2F6B4F', raised: '#8FD3B6', design: '#8FD3B6', badge: '#8FD3B6', guard: '#2F6B4F', addon: '#8FD3B6', mono: '#8FD3B6' }, addons: [] });
function pcNum(id, d, lo, hi) { const el = $(id); const v = el ? parseFloat(el.value) : NaN; return Number.isFinite(v) ? Math.max(lo, Math.min(hi, v)) : d; }
function pcOpt(id) { const el = $(id); const v = el ? parseFloat(el.value) : NaN; return Number.isFinite(v) ? v : null; }
