    patLine: pcNum('pcPatLine', 1.2, 0.6, 6), patDepth: pcNum('pcPatDepth', 0.6, 0.3, 2), patInvert: $('pcPatInvert').checked,
    text: $('pcText').value, font: radio('pcFont') || 'block', textH: pcNum('pcTextH', 7, 3, 40), textY: pcNum('pcTextY', -42, -200, 200),
    logoW: pcNum('pcLogoW', 28, 6, 160), logoY: pcNum('pcLogoY', -20, -200, 200), badgeStyle: radio('pcBadgeStyle') || 'deboss', badgeDepth: pcNum('pcBadgeDepth', 0.6, 0.3, 2),
