  const polys = window.GPClicker.traceImage(d.gray, d.w, d.h, { threshold: pcNum('pcThresh', 130, 10, 245) / 255, invert: $('pcInvert').checked, dropBg: false, smooth: 1, minFeature: 0.8, width: 40 }, d.alpha);
  PCX.image = polys.length ? polys : null;
