  const st = r.stats, f = v => (Math.round(v * 100) / 100).toString();
  const parts = r.meshes.map(m => ({ p: m.p, name: m.name, color: m.color, kind: m.kind, mat: m.mat, preview: m.preview }));
  CHX.printParts = r.print;
