  $('chGripD').value = o.gripD; $('chGripW').value = o.gripW; $('chHoles').checked = !!o.holes; $('chHoleN').value = String(o.holeN || 0); $('chHoleD').value = o.holeD;
  $('chGrooveN').value = o.grooveN; $('chGrooveDepth').value = ''; $('chPattern').value = o.pattern; $('chPatDepth').value = o.patDepth; $('chPatScale').value = o.patScale;
