  $('chGripNote').textContent = CHA.PROFILES[g].note + '.';
  $('chPadTWrap').hidden = !pad;
  const pm = CHX.preset = chPresetMatch();
  document.querySelectorAll('#chPresets button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.preset === pm)));
  $('chPresetNote').textContent = pm ? CHA.PRESETS[pm].note + '.' : 'Custom grip.';
  const holes = $('chHoles').checked; ['chHoleN', 'chHoleD'].forEach(id => { $(id).disabled = !holes; });
  $('chGrooveN').disabled = $('chGrooveDepth').disabled = (radio('chGroove') || 'none') === 'none';
  const pat = $('chPattern').value !== 'none'; ['chPatDepth', 'chPatScale'].forEach(id => { $(id).disabled = !pat; });
