function chTracePreview(polys) {
  const cv = $('chTracePrev'), cx = cv.getContext('2d');
  cx.clearRect(0, 0, cv.width, cv.height); cx.fillStyle = '#f7f7f2'; cx.fillRect(0, 0, cv.width, cv.height);
  if (!polys || !polys.length) { cv.hidden = true; return; }
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const Q of polys) for (const p of Q.outer) { if (p[0] < x0) x0 = p[0]; if (p[1] < y0) y0 = p[1]; if (p[0] > x1) x1 = p[0]; if (p[1] > y1) y1 = p[1]; }
  const pad = 8, s = Math.min((cv.width - pad * 2) / Math.max(0.01, x1 - x0), (cv.height - pad * 2) / Math.max(0.01, y1 - y0));
  const xo = (cv.width - (x1 - x0) * s) / 2, yo = (cv.height - (y1 - y0) * s) / 2;
  cx.beginPath(); for (const Q of polys) for (const L of [Q.outer, ...Q.holes]) { L.forEach((p, i) => { const X = xo + (p[0] - x0) * s, Y = cv.height - (yo + (p[1] - y0) * s); if (i) cx.lineTo(X, Y); else cx.moveTo(X, Y); }); cx.closePath(); }
  cx.fillStyle = '#e8730c'; cx.fill('evenodd'); cv.hidden = false;
}
function chTrace() {
  const d = CHX.imgData;
  if (!d) { CHX.image = null; chTracePreview(null); return; }
  const polys = window.GPClicker.traceImage(d.gray, d.w, d.h, { threshold: chNum('chThresh', 130, 10, 245) / 255, invert: $('chInvert').checked, dropBg: false, smooth: 1, minFeature: 0.8, width: 40 }, d.alpha);
  CHX.image = polys.length ? polys : null;
  $('chFileName').textContent = polys.length ? `${CHX.imageName} \u00b7 ${polys.length} outline${polys.length === 1 ? '' : 's'}` : `${CHX.imageName}: no dark shapes found. Try the threshold, invert, or a simpler image.`;
  chTracePreview(polys);
}
async function chLoadFile(f) {
  if (!f) return;
  if (!/\.(png|jpe?g|svg|webp)$/i.test(f.name) && !/^image\//.test(f.type)) { toast('Use a PNG, JPG, WebP or SVG image.'); return; }
  if (f.size > 20e6) { toast('That image is over 20 MB. Try a smaller one.'); return; }
  const url = URL.createObjectURL(f);
  try {
    const im = new Image(); im.decoding = 'async'; im.src = url; await im.decode();
    let w = im.naturalWidth || im.width, h = im.naturalHeight || im.height; if (!w || !h) w = h = 512;
    const sc = 420 / Math.max(w, h), W = Math.max(12, Math.round(w * sc)), H = Math.max(12, Math.round(h * sc));
    const cv = document.createElement('canvas'); cv.width = W + 4; cv.height = H + 4; const cx = cv.getContext('2d', { willReadFrequently: true });
    cx.imageSmoothingQuality = 'high'; cx.drawImage(im, 2, 2, W, H);
    const rgba = cx.getImageData(0, 0, W + 4, H + 4);
    CHX.imgData = { ...window.GPClicker.imageGray(rgba.data, rgba.width, rgba.height) }; CHX.imageName = f.name;
    chTrace(); chUI(); chSchedule(true);
  } catch (e) { toast('That image could not be read. Try a PNG, JPG or SVG.'); }
  finally { URL.revokeObjectURL(url); }
}
