    const sreq = { tool: 'plantpot', projectId: OUT.projectId, label: 'Seed starter tray', potShape: 'seedtray', seedCell: o.seedCell,
      seedCells: o.seedRows * o.seedCols, seedLid: !!o.seedLid, seedLabels: !!(o.seedLabels || String(o.seedName || '').trim()),
      potColors: why.some(w => /multicolor/i.test(w)) ? 2 : 1, colors: why.some(w => /multicolor/i.test(w)) ? 2 : 1, reasons: why, extras: [] };
    if (o.seedLid) sreq.extras.push('humidity lid');
