  const urls = ['earcut', 'core', 'tools', 'paint'].map(id => document.getElementById(id).src);
  const code = `importScripts(${urls.map(u => JSON.stringify(u)).join(',')});let IMG=null,R=null,RO=null;
function send(d,R){const tb=GPPaint.simTable(R.options,R.swaps),tr=[];
 const parts=R.parts.map(q=>{const p=Float32Array.from(q.p),c=GPPaint.vertexColors(q.p,tb);tr.push(p.buffer,c.buffer);return{name:q.name,color:q.color,k:q.k,p,colors:c};});
 const whole=Float32Array.from(R.whole);tr.push(whole.buffer);
 postMessage({job:d.job,type:'build',res:{parts,whole,swaps:R.swaps,size:R.size,warnings:R.warnings,stats:R.stats,detail:R.detail,closed:d.check?R.parts.every(q=>SplitCore.checkClosed(q.p).closed)&&SplitCore.checkClosed(R.whole).closed:null}},tr);}
onmessage=e=>{const d=e.data;try{
 if(d.img)IMG=d.img;
 if(d.type==='build'){R=GPPaint.build(IMG,d.opts,{detail:d.opts.detail});RO=d.opts;send(d,R);return;}
 if(d.type==='export'){if(!R||JSON.stringify(RO)!==JSON.stringify(d.opts)){R=GPPaint.build(IMG,d.opts,{detail:d.opts.detail});RO=d.opts;}
  const o={name:d.name,fileBase:d.fileBase,bambu:d.bambu,bed:d.bed};const bytes=d.kind==='3mf'?GPPaint.export3MF(R,o):StudioTools.zipBytes(GPPaint.files(R,o));
  postMessage({job:d.job,type:'export',kind:d.kind,bytes},[bytes.buffer]);return;}
}catch(err){postMessage({job:d.job,type:d.type,error:err.message||String(err)});}};`;
