  $('pnStatus').textContent = `${r.parts.length} color band${r.parts.length === 1 ? '' : 's'} \u00b7 ${st.nx} \u00d7 ${st.ny} grid (${st.cell.toFixed(2)} mm)${r.closed ? ' \u00b7 every band checked closed' : r.detail === 'draft' ? ' \u00b7 full detail on the way' : ''}.`;
